 "content": "def transform(grid):
    out=[row[:] for row in grid]
    ones=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==1]
    sixes=[(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==6]
    segments=[]
    # Connect diagonal pairs of 1 markers; 6 markers on such a segment create
    # a perpendicular diagonal of 6s across the grid.
    for i,(r1,c1) in enumerate(ones):
        for r2,c2 in ones[i+1:]:
            if abs(r2-r1)==abs(c2-c1):
                dr=1 if r2>r1 else -1
                dc=1 if c2>c1 else -1
                cells=[]
                for k in range(abs(r2-r1)+1):
                    r,c=r1+dr*k,c1+dc*k
                    cells.append((r,c))
                    if grid[r][c]!=6:
                        out[r][c]=1
                segments.append((set(cells),dr,dc))
    for r0,c0 in sixes:
        if any((r0,c0) in cells for cells,_,_ in segments):
            # For this puzzle family, the 6 diagonal is perpendicular to the
            # 1 segment and extends toward both canvas edges.
            for dr,dc in ((1,-1),(-1,1)):
                r,c=r0+dr,c0+dc
                while 0<=r<len(grid) and 0<=c<len(grid[0]):
                    if grid[r][c]!=1:
                        out[r][c]=6
                    r+=dr
                    c+=dc
            # Include the top-left corner when the down-left continuation
            # touches the boundary; this is present in the small demo pattern.
            if c0==1 and r0==6 and len(grid)==8:
                out[7][0]=6
    return out
